typedef struct { pthread_mutex_t *mu; } guard_t;
static inline void guard_release(guard_t *g) { pthread_mutex_unlock(g->mu); }

void transfer(account_t *from, account_t *to, long cents) {
    guard_t g __attribute__((cleanup(guard_release))) = { .mu = &from->lock };
    pthread_mutex_lock(g.mu);      /* released on every return path below */
    from->balance -= cents;
    to->balance += cents;
}

